# Code generated by Claude
"""
N9, the lean measurement: the base's peak tilt for straight accelerate-cruise-brake runs, in-place turns and arcs over a small grid of speeds and accelerations, with the arms at the zombie pose at the drive
pedestal height (the state in which the DRIVE starts). The staging runs as usual up to the DRIVE; there a scripted twist player takes the place of the go-to-pose controller, plays the profiles one after the
other (each from rest, with 2 s of rest between; forward and back alternate so the robot stays in the room) and reads the tilt of base_link from the live data every tick (the peak from the start of the profile
to 1.5 s after its end). The staging's own lean check is raised to 5 degrees for this run only.

    MUJOCO_GL=egl python experiments/nav_lean_sweep.py

Writes data/nav_lean_sweep.json (written to a temporary file and renamed) and prints the table. Not measured here (conservative placeholders stay): the beaker in the hand (the carrying limits), the arms at the
carry pose. A limit is proposed when its peak lean is under 0.8 degrees; the proposals come back to David (design plan 13), nothing in NAV_CFG changes.
"""

import contextlib
import io
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src import staging_source  # noqa: E402
from src.episode_runner import run_episode  # noqa: E402
from src.task_beaker_hotplate import load_task, make_task  # noqa: E402
from src.task_config import STAGING_CFG  # noqa: E402

REST_S, TAIL_S = 2.0, 1.5


def profiles():
    """(name, kind, params): straight (v, a), spin (w, alpha), arc (v, w, a, alpha)."""
    out, sign = [], 1.0
    for v in (0.3, 0.5):
        for a in (0.1, 0.2, 0.4):
            out.append((f"straight v{v} a{a}", "straight", dict(v=sign * v, a=a, dec=1.5 * a, cruise=1.0)))
            sign = -sign
    for w in (0.4, 0.8):
        for al in (0.2, 0.4, 0.8):
            out.append((f"spin w{w} alpha{al}", "spin", dict(w=sign * w, a=al, dec=al, cruise=max(0.0, (math.radians(60) - w * w / al) / w))))
            sign = -sign
    for v, w, a, al in ((0.3, 0.3, 0.2, 0.2), (0.5, 0.5, 0.2, 0.4)):
        out.append((f"arc v{v} w{w} a{a} alpha{al}", "arc", dict(v=sign * v, w=sign * w, a=a, al=al, dec=1.5 * a, cruise=1.0)))
        sign = -sign
    return out


def twist_at(kind, p, t):
    """The scripted (linear, angular) twist at time t of a profile (trapezoid), and the profile's duration."""
    x, a, dec, cruise = abs(p["v"] if kind != "spin" else p["w"]), p["a"], p["dec"], p["cruise"]
    t_up, t_dn = x / a, x / dec
    T = t_up + cruise + t_dn
    s = (t / t_up * x if t < t_up else x if t < t_up + cruise else max(0.0, x - (t - t_up - cruise) * dec)) if t < T else 0.0
    f = s / x if x > 0 else 0.0
    if kind == "straight":
        return (math.copysign(s, p["v"]), 0.0), T
    if kind == "spin":
        return (0.0, math.copysign(s, p["w"])), T
    return (p["v"] * f, p["w"] * f), T


def main():
    sim = load_task(cameras=False)
    model, data = sim.model, sim.data
    base_body = model.body("base_link").id
    plist = profiles()
    rec = {"results": [], "done": False}

    def tilt():
        return math.degrees(math.acos(max(-1.0, min(1.0, float(data.xmat[base_body][8])))))

    def fake_pose_controller(cfg, goal, *a, **k):
        S = {"leg": "SWEEP", "twist": (0.0, 0.0), "ok_since": None, "reapproach": 0, "line": None, "first_turn": None, "final_turn": None, "fail": None, "aim_missed": False}
        st = {"i": 0, "t0": None, "peak": 0.0, "phase": "rest", "tp": None}

        def reset(x, y, yaw):
            st.update(i=0, t0=None, peak=0.0, phase="rest")

        def step(obs, t, dt):
            if st["t0"] is None:
                st["t0"] = t
            if st["i"] >= len(plist):
                rec["done"] = True
                S["fail"] = "lean sweep finished"
                return [], "failed"
            name, kind, p = plist[st["i"]]
            tw, T = twist_at(kind, p, 0.0)
            if st["phase"] == "rest":
                if t - st["t0"] >= REST_S:
                    st.update(phase="run", t0=t, peak=tilt())
                return [{"mode": "base", "twist": (0.0, 0.0)}], "running"
            el = t - st["t0"]
            tw, T = twist_at(kind, p, el)
            st["peak"] = max(st["peak"], tilt())
            if el >= T + TAIL_S:
                rec["results"].append({"name": name, "kind": kind, **{k: v for k, v in p.items() if k != "cruise"}, "peak_lean_deg": st["peak"], "duration_s": T})
                print(f"  {name}: peak lean {st['peak']:.3f} deg", file=sys.__stdout__, flush=True)
                st.update(i=st["i"] + 1, t0=t, phase="rest")
                return [{"mode": "base", "twist": (0.0, 0.0)}], "running"
            return [{"mode": "base", "twist": tw}], "running"
        return {"reset": reset, "step": step, "S": S}

    orig = staging_source._pose_controller
    staging_source._pose_controller = fake_pose_controller
    cfg = dict(STAGING_CFG, drive_max_lean_deg=5.0, drive_timeout=3000.0)
    try:
        task = make_task(None, staging_cfg=cfg)
        with contextlib.redirect_stdout(io.StringIO()) as buf:
            s = run_episode(task, model, data, stop_after_handoff_s=0.5)
    finally:
        staging_source._pose_controller = orig
    print("episode:", s["outcome"], s.get("staging_error"))
    ok_runs = [r for r in rec["results"] if r["peak_lean_deg"] < 0.8]
    print(f"\n{len(rec['results'])} profiles, {len(ok_runs)} under 0.8 degrees; sweep finished: {rec['done']}")
    out = PROJECT_ROOT / "data" / "nav_lean_sweep.json"
    tmp = out.with_suffix(".json.tmp")
    tmp.write_text(json.dumps({"results": rec["results"], "finished": rec["done"], "drive_pedestal_q": None, "note": "arms at the zombie pose, beaker not held"}, indent=1))
    tmp.replace(out)
    return rec["done"] and len(rec["results"]) == len(plist)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
